import type { CollectionMeta, SingletonMeta } from "../collections";
import type { WirePathHints } from "./freeFormPaths";

const GENERATED_HEADER = `// Generated by @autumn/atmn-generator from packages/openapi/openapi-internal.yml.
// Do not edit — run \`bun generate\` in packages/atmn-generator instead.
`;

/**
 * The walker is emitted rather than hand-written so that nothing concept-aware
 * lives outside the generator. It is identical for every collection; what
 * differs is the hints, which come from the spec.
 */
const RUNTIME = `
/** Operators like \`$startsWith\` are literal API keys, not snake_case fields. */
const isOperatorKey = (key: string): boolean => key.startsWith("$");

/** Only \`_\` before a LETTER folds — \`_1\` has no uppercase form to restore. */
const toSnakeCase = (key: string): string =>
	isOperatorKey(key) ? key : key.replace(/[A-Z]/g, (c) => \`_\${c.toLowerCase()}\`);

const toCamelCase = (key: string): string =>
	isOperatorKey(key)
		? key
		: key.replace(/_([a-z])/g, (_, c: string) => c.toUpperCase());

export type PathHints = {
	recordPaths: Set<string>;
	frozenPaths: Set<string>;
	/** Fixture path -> wire key, where the overlay renamed a field. */
	renamedPaths: Map<string, string>;
	/** Wire path -> fixture name: the same renames, read from a response. */
	renamedWirePaths: Map<string, string>;
};

export type WireDocument = Record<string, unknown>;

/**
 * Fixture (camelCase) -> wire (snake_case), stopping where the spec says the
 * data stops being ours. Array indices are elided from the path, so one hint
 * covers every element.
 */
export const toWire = ({
	value,
	path,
	hints,
}: {
	value: unknown;
	path: string;
	hints: PathHints;
}): unknown => {
	if (hints.frozenPaths.has(path)) return value;

	if (Array.isArray(value)) {
		return value.map((entry) => toWire({ value: entry, path, hints }));
	}
	if (value === null || typeof value !== "object") return value;

	const source = value as Record<string, unknown>;

	// A record's keys are the user's; its values are still ours.
	if (hints.recordPaths.has(path)) {
		return Object.fromEntries(
			Object.entries(source).map(([key, entry]) => [
				key,
				toWire({ value: entry, path: \`\${path}.*\`, hints }),
			]),
		);
	}

	return Object.fromEntries(
		Object.entries(source).map(([key, entry]) => {
			const childPath = path ? \`\${path}.\${key}\` : key;
			return [
				hints.renamedPaths.get(childPath) ?? toSnakeCase(key),
				toWire({ value: entry, path: childPath, hints }),
			];
		}),
	);
};

/**
 * Wire (snake_case) -> fixture (camelCase), for responses. Hints are recorded
 * in FIXTURE terms, so the path is built from the recased key.
 */
export const toFixture = ({
	value,
	path,
	hints,
}: {
	value: unknown;
	path: string;
	hints: PathHints;
}): unknown => {
	if (hints.frozenPaths.has(path)) return value;

	if (Array.isArray(value)) {
		return value.map((entry) => toFixture({ value: entry, path, hints }));
	}
	if (value === null || typeof value !== "object") return value;

	const source = value as Record<string, unknown>;

	if (hints.recordPaths.has(path)) {
		return Object.fromEntries(
			Object.entries(source).map(([key, entry]) => [
				key,
				toFixture({ value: entry, path: \`\${path}.*\`, hints }),
			]),
		);
	}

	return Object.fromEntries(
		Object.entries(source).map(([key, entry]) => {
			const name =
				hints.renamedWirePaths.get(path ? \`\${path}.\${key}\` : key) ??
				toCamelCase(key);
			return [
				name,
				toFixture({
					value: entry,
					path: path ? \`\${path}.\${name}\` : name,
					hints,
				}),
			];
		}),
	);
};

export const hintsOf = (hints: {
	recordPaths: readonly string[];
	frozenPaths: readonly string[];
	renamedPaths: Readonly<Record<string, string>>;
}): PathHints => ({
	recordPaths: new Set(hints.recordPaths),
	frozenPaths: new Set(hints.frozenPaths),
	renamedPaths: new Map(Object.entries(hints.renamedPaths)),
	renamedWirePaths: new Map(
		Object.entries(hints.renamedPaths).map(([fixturePath, wireKey]) => {
			const segments = fixturePath.split(".");
			const parent = segments.slice(0, -1);
			return [[...parent, wireKey].join("."), segments[segments.length - 1] ?? ""];
		}),
	),
});
`;

const hintsLiteral = ({
	name,
	hints,
}: {
	name: string;
	hints: WirePathHints;
}): string =>
	`const ${name} = hintsOf({
	recordPaths: ${JSON.stringify(hints.recordPaths)},
	frozenPaths: ${JSON.stringify(hints.frozenPaths)},
	renamedPaths: ${JSON.stringify(hints.renamedPaths)},
});`;

/**
 * `atmn()` is the whole client-side computation: fold history into its
 * collection, lint, recase, and state two constants. Every decision the config
 * used to carry — versioning, propagation, which plans need a migration — is
 * the server's now. An omitted collection stays omitted: absent means "not
 * mine", `[]` means "mine, and empty".
 */
export const emitWireModule = ({
	catalogHints,
	collections,
	singletons,
}: {
	catalogHints: WirePathHints;
	collections: Readonly<Record<string, CollectionMeta>>;
	singletons: Readonly<Record<string, SingletonMeta>>;
}): string => {
	const entries = Object.entries(collections);
	const singletonEntries = Object.entries(singletons);
	const imports = [...entries, ...singletonEntries]
		.map(([name, meta]) => `import type { ${meta.typeName} } from "./${name}";`)
		.join("\n");
	const singletonMembers = singletonEntries
		.flatMap(([name, meta]) => [
			`\t/** The ${name} this config manages. Only the fields stated are written;`,
			`\t * an omitted field keeps its value, and an omitted block manages nothing. */`,
			`\t${name}?: ${meta.typeName};`,
		])
		.join("\n");
	const singletonStated = singletonEntries
		.map(
			([name]) =>
				`\t...(config.${name} !== undefined ? { ${name}: config.${name} } : {}),`,
		)
		.join("\n");
	const singletonKeys = JSON.stringify(singletonEntries.map(([name]) => name));
	const singletonBodies = singletonEntries
		.map(
			([name, meta]) =>
				`\t\t${name}: document.${name} === undefined ? undefined : { ${meta.wireKey}: document.${name} },`,
		)
		.join("\n");
	const members = entries
		.flatMap(([name, meta]) => [
			`\t/** Every ${name} entry this catalog should have. \`[]\` means "mine, and`,
			`\t * empty"; omitted means "not mine". */`,
			`\t${name}?: ${meta.typeName}[];`,
			...(meta.historyKey
				? [
						`\t/** Past versions of ${name}, full rows, stamped \`active: false\`. */`,
						`\t${meta.historyKey}?: ${meta.typeName}[];`,
					]
				: []),
		])
		.join("\n");
	const stated = entries
		.map(([name, meta]) =>
			meta.historyKey
				? `\t...(config.${name} !== undefined
\t\t? {
\t\t\t\t${name}: [
\t\t\t\t\t...config.${name}.map((row) => followDeclaredVariants({ ...row, active: row.active ?? true })),
\t\t\t\t\t...(config.${meta.historyKey} ?? []).map((row) => followDeclaredVariants({ ...row, active: false })),
\t\t\t\t],
\t\t\t\t// Absent history is "not mine"; stated history removes the versions it omits.
\t\t\t\tskip_version_deletions: config.${meta.historyKey} === undefined,
\t\t\t}
\t\t: {}),`
				: `\t...(config.${name} !== undefined ? { ${name}: config.${name} } : {}),`,
		)
		.join("\n");
	const guards = entries
		.filter(([, meta]) => meta.historyKey)
		.map(
			([
				name,
				meta,
			]) => `\tif (config.${meta.historyKey} !== undefined && config.${name} === undefined) {
\t\tthrow new ConfigError([
\t\t\t{
\t\t\t\tpath: "config",
\t\t\t\tmessage: "${meta.historyKey} needs ${name}: history rows on their own would remove every active version.",
\t\t\t},
\t\t]);
\t}`,
		)
		.join("\n");

	return [
		GENERATED_HEADER,
		`${imports}
import { LINT_RULES } from "./lintRules";
import { ConfigError, lintDocument } from "./lintRuntime";`,
		RUNTIME,
		hintsLiteral({ name: "CATALOG_HINTS", hints: catalogHints }),
		`
export type AtmnConfig = {
${members}
${singletonMembers}
};

/** The document as the server sees it: history rows folded into their collection. */
/** A declared variant with no customize of its own follows its base: the
 * server needs the pin stated, so it is derived here, never typed. */
const followDeclaredVariants = <
	T extends {
		variants?: { variantPlanId: string; version?: number; versionSlug?: string }[];
	},
>(
	row: T,
): T & {
	propagate?: {
		variants: { planId: string; version?: number; versionSlug?: string }[];
	};
} =>
	Array.isArray(row.variants) && row.variants.length > 0
		? {
				...row,
				propagate: {
					// A declared version pin travels with the follow, or the server
					// would resolve the active variant row instead of the stated one.
					variants: row.variants.map((variant) => ({
						planId: variant.variantPlanId,
						...(variant.version !== undefined ? { version: variant.version } : {}),
						...(variant.versionSlug !== undefined ? { versionSlug: variant.versionSlug } : {}),
					})),
				},
			}
		: row;

const stated = (config: AtmnConfig): Record<string, unknown> => ({
${stated}
${singletonStated}
});

const SINGLETON_KEYS: readonly string[] = ${singletonKeys};

/**
 * The catalog document and each singleton's own request body, split from the
 * one document \`atmn()\` returns: they go to different operations.
 */
export const splitWire = (
	document: WireDocument,
): {
	catalog: WireDocument;
	singletons: Record<string, WireDocument | undefined>;
} => ({
	catalog: Object.fromEntries(
		Object.entries(document).filter(([key]) => !SINGLETON_KEYS.includes(key)),
	),
	singletons: {
${singletonBodies}
	},
});

export const atmn = (config: AtmnConfig): WireDocument => {
${guards}
	const document = stated(config);
	// Linted before anything is sent, and every problem is reported at once —
	// a round trip per mistake is what makes a config painful to write.
	const issues = lintDocument({
		document,
		rules: LINT_RULES,
		hints: CATALOG_HINTS,
	});
	if (issues.length > 0) throw new ConfigError(issues);

	return {
		...(toWire({ value: document, path: "", hints: CATALOG_HINTS }) as WireDocument),
		// The payload is the complete desired catalog, so omission is a removal.
		skip_deletions: false,
		// A constant, not a decision: "draft wherever one is warranted". The server
		// works out which rows actually need one.
		migration: { draft: true },
	};
};
`,
	].join("\n");
};
